using System;using System.Linq;using System.IO;using System.Reflection;using Verse;using Verse.AI;using PlayableRecreation;using PlayableRecreation.UI;using PRQA;
public static class Command{public static string Run(){Host.Watch=null;var pair=(Pawn[])Host.State["pair"];var p=pair[0];var o=pair[1];var b=(Thing)Host.State["chess"];var comp=b.TryGetComp<CompMiniGame>();var log=Host.Root+"/resume-paths.txt";File.WriteAllText(log,"Saved two-player game, actual gizmo/menu/GoToGame pathways.\n");Action<string> note=s=>File.AppendAllText(log,s+"\n");o.drafter.Drafted=true;comp.CompGetGizmosExtra().OfType<Command_Action>().First().action();note("drafted gizmo immediateWindow="+Find.WindowStack.Windows.Any(w=>w is Dialog_MiniGame));p.jobs.EndCurrentJob(JobCondition.InterruptForced);p.Position=b.Position+new IntVec3(-8,0,-4);p.Notify_Teleported();GameEntry.Begin(comp.Game,b,p);int start=Find.TickManager.TicksGame,stage=0;bool sawWindow=false;Host.Watch=()=>{int e=Find.TickManager.TicksGame-start;var d=Find.WindowStack.Windows.OfType<Dialog_MiniGame>().FirstOrDefault();sawWindow|=d!=null;if(stage==0&&e>600){note("drafted walk-to-open windowSeen="+sawWindow+" stored="+(GameEntry.SessionFor(b)!=null)+" jobs="+p.CurJobDef+","+o.CurJobDef);o.drafter.Drafted=false;o.jobs.EndCurrentJob(JobCondition.InterruptForced);o.Position=b.Position+new IntVec3(8,0,-4);o.Notify_Teleported();o.needs.food.CurLevelPercentage=1;o.needs.rest.CurLevelPercentage=1;comp.CompFloatMenuOptions(p).First().action();note("available menu immediateWindow="+Find.WindowStack.Windows.Any(w=>w is Dialog_MiniGame));stage=1;start=Find.TickManager.TicksGame;}else if(stage==1&&(d!=null||e>1200)){note("available reopened="+(d!=null)+" ticks="+e+" positions="+p.Position+","+o.Position+" seats="+p.CurJob?.targetC+","+o.CurJob?.targetC+" rotations="+p.Rotation.AsInt+","+o.Rotation.AsInt+" jobs="+p.CurJobDef+","+o.CurJobDef);Host.State["resumeWindow"]=d;Host.Watch=null;Find.TickManager.CurTimeSpeed=TimeSpeed.Paused;}};Find.TickManager.CurTimeSpeed=TimeSpeed.Superfast;return "Gizmo, walking, and available menu resume running.";}}
